struct Quote {
    let list: Decimal        // crossed "Before" price
    let subtotal: Decimal    // after the duration offer
    let couponCut: Decimal
    let methodDelta: Decimal
    var total: Decimal { max(0, subtotal - couponCut - methodDelta) }
    var saved: Decimal { list - total }
}

func quote(duration: Duration, coupon: Coupon?, method: PayMethod?) -> Quote {
    let sub = duration.now
    let cut: Decimal = {
        guard let c = coupon else { return 0 }
        switch c.kind {
        case .flat(let v):          return min(sub, v)
        case .percent(let p, let cap): return min(cap, sub * p / 100)
        }
    }()
    return Quote(list: duration.was, subtotal: sub,
                 couponCut: cut, methodDelta: method?.delta ?? 0)
}

